package vn.iotstar.example1.entity; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="users") @Getter @Setter @NoArgsConstructor @AllArgsConstructor public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=120) private String email; @Column(nullable=false,length=150) private String password; @Column(nullable=false,columnDefinition="nvarchar(120)") private String fullName; @Column(nullable=false) private boolean enabled=true; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="role_id",nullable=false) private Role role; }
